import{_ as a,a as o,b as i,c as p,d as e,e as r}from"./chunks/image8.CTney3UO.js";import{_ as u,o as n,c as s,ag as l}from"./chunks/framework.D9ghT4bC.js";const b=JSON.parse('{"title":"Unciv 联机教程","description":"","frontmatter":{"title":"Unciv 联机教程"},"headers":[],"relativePath":"zh/Community/Guides/Multiplayer-tutorial/index.md","filePath":"zh/Community/Guides/Multiplayer-tutorial/index.md"}'),c={name:"zh/Community/Guides/Multiplayer-tutorial/index.md"};function d(m,t,q,_,h,I){return n(),s("div",null,[...t[0]||(t[0]=[l('<h1 id="unciv-联机教程" tabindex="-1">Unciv 联机教程 <a class="header-anchor" href="#unciv-联机教程" aria-label="Permalink to &quot;Unciv 联机教程&quot;">​</a></h1><blockquote><p>作者：SpringPizazz</p><p>完稿日期：2024年3月27日</p></blockquote><p>联机之前，首先要了解 UID：UID 是用户身份证明（User Identification）的缩写，在 Unciv 的联机中，UID 分为玩家 ID 和房间 ID 两种，玩家 ID 用于辨识不同玩家，房间 ID 用于辨识不同对局。</p><p>此外，玩家需要允许 Unciv 程序访问剪贴板（尤其是安卓端）以便 Unciv 获取这两类 UID。</p><p>此外，所有对局参与者都需要严格保证游戏版本相同，模组相同，模组版本相同以避免未知错误。</p><h2 id="与联机服务器建立联系" tabindex="-1">与联机服务器建立联系 <a class="header-anchor" href="#与联机服务器建立联系" aria-label="Permalink to &quot;与联机服务器建立联系&quot;">​</a></h2><p>打开主菜单，点击&quot;选项&quot;按钮，</p><p><img src="'+a+'" alt="与联机服务器建立联系 - 步骤1"></p><p>点击上方&quot;多人游戏&quot;按钮，</p><p><img src="'+o+'" alt="与联机服务器建立联系 - 步骤2"></p><p>客户端已显示社区服务器地址 <code>https://unciv.civgo.top:30123</code>。点击<strong>检测连接</strong>，确认能访问服务器并登录。请设置密码以保护你的玩家 ID。</p><h2 id="获取玩家-id" tabindex="-1">获取玩家 ID <a class="header-anchor" href="#获取玩家-id" aria-label="Permalink to &quot;获取玩家 ID&quot;">​</a></h2><p>回到主菜单，点击&quot;多人游戏&quot;按钮，</p><p>点击&quot;复制玩家 ID&quot;按钮，</p><p><img src="'+i+'" alt="获取玩家ID"></p><p>现在你的玩家 ID 就存放在剪贴板上了！</p><p>如果你是对局发起者，请保留你的玩家 ID；如果你是对局参与者，请把这段玩家 ID 通过社交媒体（如 QQ）发送给对局发起者并声明这是玩家 ID（而不是对局 ID）。</p><h2 id="房主创建房间" tabindex="-1">房主创建房间 <a class="header-anchor" href="#房主创建房间" aria-label="Permalink to &quot;房主创建房间&quot;">​</a></h2><p>回到主菜单，点击&quot;开始新游戏&quot;按钮，</p><p>点击&quot;在线多人游戏&quot;按钮，</p><p><img src="'+p+'" alt="房主创建房间 - 步骤1"></p><p>将玩家 ID 粘贴到对应的文本框内并选择对应的国家</p><p><img src="'+e+'" alt="房主创建房间 - 步骤2"></p><p>选择相应的地图配置后，点击右下角&quot;开始游戏！&quot;按钮，进入到游戏主屏幕，此时房间 ID 将自动保存到剪贴板，将这个房间 ID 发送给所有对局参与者并声明这是房间 ID 而不是玩家 ID。</p><h2 id="参与者加入房间" tabindex="-1">参与者加入房间 <a class="header-anchor" href="#参与者加入房间" aria-label="Permalink to &quot;参与者加入房间&quot;">​</a></h2><p>参与者复制房主发送的房间 ID 到剪贴板，</p><p>回到主菜单，点击&quot;多人游戏&quot;按钮，</p><p>点击&quot;新增多人游戏&quot;，</p><p><img src="'+r+'" alt="参与者加入房间"></p><p>在第一个文本框粘贴房间 ID，在第二个文本框输入你对此对局的备注，如不填则被房间 ID 覆盖。</p><p>输入完毕后点击右下角&quot;保存游戏&quot;按钮，回到上一页面，再点击多出的显示刚才备注的按钮，点击右下角&quot;开始游戏&quot;，即可参与对局。</p>',31)])])}const v=u(c,[["render",d]]);export{b as __pageData,v as default};
